import{_ as e,c as o,o as n,ae as a}from"./chunks/framework.Bi6zybwU.js";const p=JSON.parse('{"title":"Text Icon (Pro)","description":"Text Icon (Pro)","frontmatter":{"title":"Text Icon (Pro)","description":"Text Icon (Pro)"},"headers":[],"relativePath":"guide/drag-drop-elements/text-icon-pro.md","filePath":"guide/drag-drop-elements/text-icon-pro.md"}'),r={name:"guide/drag-drop-elements/text-icon-pro.md"};function i(l,t,s,d,c,h){return n(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="text-icon-pro" tabindex="-1">Text Icon (Pro) <a class="header-anchor" href="#text-icon-pro" aria-label="Permalink to &quot;Text Icon (Pro)&quot;">​</a></h1><p>In the Ninja Tables Drag and Drop mode, you&#39;ll find Text Icon element. This element lets you add text beside an icon and it&#39;s only available as a pro element. It&#39;s almost similar to the &quot;<a href="https://ninjatables.com/docs/styled-list/" target="_blank" rel="noreferrer">Styled List</a>&quot; element because of the use of an icon and a text box side by side. However, the Text Icon element is a single text box and not a list. Unless you stack them as a list. Let’s add a <strong>Text Icon</strong> element to our Ninja Tables and check its properties and possibilities. Follow this path- <strong>Elements &gt;&gt; Advanced &gt;&gt; Text Icon</strong>. <img src="https://ninjatables.com/wp-content/uploads/2023/08/Text-Icon-Drag-and-Drop-1024x567.png" alt="Text Icon Drag and Drop"> You can click the &quot;Text Icon&quot; cell and customize the icon and text both.</p><h2 id="properties-of-text-icon-element" tabindex="-1"><strong>Properties of Text Icon Element</strong> <a class="header-anchor" href="#properties-of-text-icon-element" aria-label="Permalink to &quot;**Properties of Text Icon Element**&quot;">​</a></h2><table tabindex="0"><thead><tr><th><strong>Scope</strong></th><th><strong>Option Name</strong></th><th><strong>Type</strong></th></tr></thead><tbody><tr><td>General</td><td>Editor Box</td><td>Text Editor</td></tr><tr><td></td><td>Item Spacing</td><td>Numeric Value, drag bar</td></tr><tr><td></td><td>Alignment</td><td>Left, Center, and Right</td></tr><tr><td>Text</td><td>Font Color</td><td>Graphical Color Selection</td></tr><tr><td></td><td>Font Size</td><td>Numeric Value, drag bar</td></tr><tr><td></td><td>Font Style</td><td>Bold, Italic &amp; Underline</td></tr><tr><td>Icon</td><td>Color</td><td>Graphical Color Selection</td></tr><tr><td></td><td>Icon Size</td><td>Numeric Value, drag bar</td></tr><tr><td></td><td>Choose Icon</td><td>Upload from Computer</td></tr><tr><td></td><td>Icon Library</td><td>Selection from Library</td></tr><tr><td></td><td>Icon Position</td><td>Left &amp; Right</td></tr></tbody></table><h3 id="general" tabindex="-1"><strong>General</strong> <a class="header-anchor" href="#general" aria-label="Permalink to &quot;**General**&quot;">​</a></h3><p><img src="https://ninjatables.com/wp-content/uploads/2023/08/Text-Icon-element-2-1024x436.png" alt="Text Icon element"></p><ul><li>**Editor box: **A text editor where you can edit your element text.</li><li><strong>Item Spacing:</strong> You can add space or gap between the Icons and text Items. By default, It is set to 0.</li><li>**Alignment: **Align the text and icon to the left, right, or center. By default, it is set to center.</li></ul><h3 id="text" tabindex="-1"><strong>Text</strong> <a class="header-anchor" href="#text" aria-label="Permalink to &quot;**Text**&quot;">​</a></h3><p><img src="https://ninjatables.com/wp-content/uploads/2023/08/text-icon-customize-1024x474.png" alt="text icon customize"></p><ul><li><strong>Font Color</strong>: You can change the color of the text. By default, it is set to Black.</li><li><strong>Font Size</strong>: You can change the size of the text. By default, it is set to 10.</li><li><strong>Font Style</strong>: You can change the Font Style orientations. Available options are <strong>Bold</strong>, <em>Italic</em>, and Underline.</li></ul><h3 id="icon" tabindex="-1"><strong>Icon</strong> <a class="header-anchor" href="#icon" aria-label="Permalink to &quot;**Icon**&quot;">​</a></h3><p><img src="https://ninjatables.com/wp-content/uploads/2023/08/text-icon-color-1024x512.png" alt="text icon color"></p><ul><li><strong>Color:</strong> You can change the color of the Icon. By default, it is set to Black.</li><li><strong>Icon Size:</strong> You can change the size of the Icon. By default, it is set to 10.</li><li><strong>Choose Icon:</strong> You can upload any image as an icon for your “Text icon” element.</li><li><strong>Icon Library:</strong> There are plenty of Icons to choose from in the library. By default, it is set to a black Ninja Tables logo.</li><li><strong>Icon Position:</strong> You can position the icon left or right to the text. By default, it is set to left.</li></ul><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Use a text icon element on your data table to make it dynamic and not a boring table with text only. A relevant icon with a text can make the table appear more engaging. Let us know your thoughts and questions in the comment box.</p>',15)])])}const u=e(r,[["render",i]]);export{p as __pageData,u as default};
